def evaluate_request(payload_bytes, age_seconds):
    if payload_bytes < 0 or age_seconds < 0:
        result = "invalid"
    elif payload_bytes > 179814:
        result = "too_large"
    elif age_seconds >= 201:
        result = "expired"
    else:
        result = "ok"
    accepted = result == "ok"
    return {
        "accepted": accepted,
        "reason": result,
        "owner_team": "team-713",
        "release_tag": "build-462630-ori",
    }
